package com.tekwatt.admin.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="admin_api_keys")public class AdminApiKey{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false,unique=true,length=40)private String keyId;@Column(nullable=false,length=64)private String secretHash;@Column(nullable=false,length=120)private String name;@Column(nullable=false,length=60)private String roleName;@Column(nullable=false,length=1000)private String scopes;@Column(nullable=false,length=20)private String status;@Column(nullable=false)private Instant createdAt;private Instant lastUsedAt;protected AdminApiKey(){}public AdminApiKey(UUID t,String key,String hash,String n,String role,String scopes){id=UUID.randomUUID();tenantId=t;keyId=key;secretHash=hash;name=n;roleName=role;this.scopes=scopes;status="ACTIVE";createdAt=Instant.now();}public void disable(){status="DISABLED";}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public String getKeyId(){return keyId;}public String getName(){return name;}public String getRoleName(){return roleName;}public String getScopes(){return scopes;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getLastUsedAt(){return lastUsedAt;}}
